  var sample: PathSample;

  sample.position = vec3f(

    mix(-aspect * 1.28, aspect * 1.28, t),

    -0.86 + sin(t * pi) * 0.28 + sin(t * pi * 3.0) * 0.06,

    cos(t * pi * 2.0) * 0.16,

  );

  sample.tangent = safeNormalize(derivative);

  sample.phase = phase;

  return sample;

